        return hasToast(this.toasts, name);
    }
    subscribe(listener) {
        const unsubscribe = this.eventEmitter.subscribe('toasts-change', listener);
        if (this.hasUndelivered) {
            this.notify();
        }
        return unsubscribe;
    }
